    '\u0410\u043d\u0430\u043b\u0456\u0442\u0438\u0447\u043d\u0435 \u043c\u0438\u0441\u043b\u0435\u043d\u043d\u044f \u2013 \u0437\u0434\u0430\u0442\u043d\u0456\u0441\u0442\u044c \u0430\u043d\u0430\u043b\u0456\u0437\u0443\u0432\u0430\u0442\u0438 \u0432\u0435\u043b\u0438\u043a\u0456 \u043e\u0431\u0441\u044f\u0433\u0438 \u0447\u0438\u0441\u043b\u043e\u0432\u043e\u0457 \u0456\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u0457 \u0442\u0430 \u0440\u043e\u0431\u0438\u0442\u0438 \u043e\u0431\u0491\u0440\u0443\u043d\u0442\u043e\u0432\u0430\u043d\u0456 \u0432\u0438\u0441\u043d\u043e\u0432\u043a\u0438. '
    '\u0412\u043e\u043b\u043e\u0434\u0456\u044e \u043d\u0430\u0432\u0438\u0447\u043a\u0430\u043c\u0438 \u0440\u043e\u0431\u043e\u0442\u0438 \u0437 Microsoft Excel (\u043f\u0440\u043e\u0441\u0443\u043d\u0443\u0442\u0438\u0439 \u0440\u0456\u0432\u0435\u043d\u044c), \u043e\u0441\u043d\u043e\u0432\u0430\u043c\u0438 Python \u0434\u043b\u044f \u0430\u043d\u0430\u043b\u0456\u0437\u0443 \u0434\u0430\u043d\u0438\u0445, '
