    '\u043c\u043e\u0436\u043b\u0438\u0432\u0456\u0441\u0442\u044c \u043f\u0440\u0438\u043d\u043e\u0441\u0438\u0442\u0438 \u043a\u043e\u0440\u0438\u0441\u0442\u044c \u0441\u0443\u0441\u043f\u0456\u043b\u044c\u0441\u0442\u0432\u0443, \u0431\u0430\u043b\u0430\u043d\u0441 \u043c\u0456\u0436 \u0440\u043e\u0431\u043e\u0442\u043e\u044e \u0442\u0430 \u043e\u0441\u043e\u0431\u0438\u0441\u0442\u0438\u043c \u0436\u0438\u0442\u0442\u044f\u043c, '
    '\u0447\u0435\u0441\u043d\u0456\u0441\u0442\u044c \u0442\u0430 \u0435\u0442\u0438\u0447\u043d\u0456\u0441\u0442\u044c \u0443 \u0434\u0456\u043b\u043e\u0432\u0438\u0445 \u0432\u0456\u0434\u043d\u043e\u0441\u0438\u043d\u0430\u0445. '
    '\u041c\u0435\u043d\u0456 \u0432\u0430\u0436\u043b\u0438\u0432\u043e, \u0449\u043e\u0431 \u043c\u043e\u044f \u043f\u0440\u0430\u0446\u044f \u043c\u0430\u043b\u0430 \u0456\u043d\u0442\u0435\u043b\u0435\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u0438\u0439 \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440 \u0456 \u0434\u0430\u0432\u0430\u043b\u0430 \u043c\u043e\u0436\u043b\u0438\u0432\u0456\u0441\u0442\u044c \u043f\u043e\u0441\u0442\u0456\u0439\u043d\u043e \u0440\u043e\u0437\u0432\u0438\u0432\u0430\u0442\u0438\u0441\u044f.'
