run.bold = True
doc.add_paragraph(
    '\u042f \u2013 \u0441\u0442\u0443\u0434\u0435\u043d\u0442 3-\u0433\u043e \u043a\u0443\u0440\u0441\u0443 \u0435\u043a\u043e\u043d\u043e\u043c\u0456\u0447\u043d\u043e\u0433\u043e \u0444\u0430\u043a\u0443\u043b\u044c\u0442\u0435\u0442\u0443, \u0446\u0456\u043b\u0435\u0441\u043f\u0440\u044f\u043c\u043e\u0432\u0430\u043d\u0430 \u043e\u0441\u043e\u0431\u0438\u0441\u0442\u0456\u0441\u0442\u044c \u0437 \u0430\u043d\u0430\u043b\u0456\u0442\u0438\u0447\u043d\u0438\u043c \u0441\u043a\u043b\u0430\u0434\u043e\u043c \u0440\u043e\u0437\u0443\u043c\u0443. '
    '\u041c\u043e\u0457 \u0441\u0438\u043b\u044c\u043d\u0456 \u0441\u0442\u043e\u0440\u043e\u043d\u0438: \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0430\u043b\u044c\u043d\u0456\u0441\u0442\u044c, \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u0456\u0441\u0442\u044c, \u0437\u0434\u0430\u0442\u043d\u0456\u0441\u0442\u044c \u0434\u043e \u0441\u0430\u043c\u043e\u043d\u0430\u0432\u0447\u0430\u043d\u043d\u044f, \u0443\u0432\u0430\u0436\u043d\u0456\u0441\u0442\u044c \u0434\u043e \u0434\u0435\u0442\u0430\u043b\u0435\u0439. '
    '\u0421\u043b\u0430\u0431\u043a\u0456 \u0441\u0442\u043e\u0440\u043e\u043d\u0438: \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043d\u0456\u0439 \u043f\u0440\u0430\u043a\u0442\u0438\u0447\u043d\u0438\u0439 \u0434\u043e\u0441\u0432\u0456\u0434, \u0456\u043d\u043e\u0434\u0456 \u043d\u0435\u0441\u0442\u0430\u0447\u0430 \u0432\u043f\u0435\u0432\u043d\u0435\u043d\u043e\u0441\u0442\u0456 \u043f\u0456\u0434 \u0447\u0430\u0441 \u043f\u0443\u0431\u043b\u0456\u0447\u043d\u0438\u0445 \u0432\u0438\u0441\u0442\u0443\u043f\u0456\u0432. '
    '\u042f \u0431\u0430\u0447\u0443 \u0441\u0435\u0431\u0435 \u044f\u043a \u043c\u0430\u0439\u0431\u0443\u0442\u043d\u044c\u043e\u0433\u043e \u0444\u0456\u043d\u0430\u043d\u0441\u043e\u0432\u043e\u0433\u043e \u0430\u043d\u0430\u043b\u0456\u0442\u0438\u043a\u0430, \u044f\u043a\u0438\u0439 \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u043e\u0431\u0491\u0440\u0443\u043d\u0442\u043e\u0432\u0430\u043d\u0456 \u0440\u0456\u0448\u0435\u043d\u043d\u044f \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u0456 \u0434\u0430\u043d\u0438\u0445.'
)

